import * as React from "react";

import { useStaticQuery, graphql, Script } from "gatsby";

const Seo = ({ title, description, image }) => {
  const { site } = useStaticQuery(
    graphql`
      query {
        site {
          siteMetadata {
            title
            description
            author
            keywords
            siteUrl
            image
          }
        }
      }
    `
  );

  const seo = [
    {
      name: "description",
      content: description ? description : site.siteMetadata.description,
    },
    {
      name: "keywords",
      content: site.siteMetadata.keywords,
    },
    {
      property: "og:title",
      content: title ? title : site.siteMetadata.title,
    },
    {
      property: "og:description",
      content: description ? description : site.siteMetadata.description,
    },
    {
      property: "og:image",
      content: image ? image : site.siteMetadata.image,
    },
    {
      property: "og:type",
      content: "website",
    },
    {
      name: "twitter:creator",
      content: site.siteMetadata.author,
    },
    {
      name: "twitter:title",
      content: title ? title : site.siteMetadata.title,
    },
    {
      name: "twitter:description",
      content: description ? description : site.siteMetadata.description,
    },
  ];

  return (
    <>
      <title>Porównaj ceny domen internetowych u rożnych rejestratorów</title>
      <meta name="description" content={seo.description} />
      <meta name="image" content={seo.image} />
    </>
  );
};

export default Seo;
